// At 100,000 RPS, even a single Redis key ('viral_video_views') melts at ~100k ops/sec
// Solution: Coalesce writes in local pod memory for 1000ms before flushing 1 HINCRBY to Redis!
export class WriteBehindCounterAggregator {
  private localDeltas = new Map<string, number>();

  public increment(entityId: string, delta = 1): void {
    this.localDeltas.set(entityId, (this.localDeltas.get(entityId) ?? 0) + delta);
  }

  // Invoked every 1,000ms by background timer
  public async flushToDistributedStore(redis: RedisClient): Promise<void> {
    const batch = new Map(this.localDeltas);
    this.localDeltas.clear();
    const pipeline = redis.pipeline();
    for (const [id, count] of batch.entries()) {
      pipeline.hincrby('entity_counters', id, count);
    }
    await pipeline.exec(); // Reduces 50,000 network ops/sec -> 1 batched pipeline/sec!
  }
}
